"""Review harness for the VarsWithSources union fix (DEV-6).

Usage: <venv-python> -I review/check_semantics.py <repo-root>
Imports ansible from <repo-root>/lib and prints one line per check;
every check is isolated so one crash does not hide the others.
"""
import collections
import sys

sys.path.insert(0, sys.argv[1] + '/lib')

from unittest import mock  # noqa: E402

from ansible.errors import AnsibleError  # noqa: E402
from ansible.utils.display import Display  # noqa: E402
from ansible.utils.vars import combine_vars  # noqa: E402
from ansible.vars.manager import VarsWithSources  # noqa: E402

failures = []


def vws(**kw):
    return VarsWithSources.new_vars_with_sources(dict(kw), {k: 'src_' + k for k in kw})


def check(name, fn):
    """fn returns (ok, detail)."""
    try:
        ok, detail = fn()
    except Exception as e:
        ok, detail = False, 'raised %s: %s' % (type(e).__name__, e)
    print('%-4s %s%s' % ('OK' if ok else 'FAIL', name, ('  [%s]' % detail) if detail else ''))
    if not ok:
        failures.append(name)


def raises(exc, fn):
    try:
        fn()
    except exc:
        return True, ''
    except Exception as e:
        return False, 'wrong exception %r' % e
    return False, 'no exception'


def union_case(left, right, expected):
    snap_l, snap_r = dict(left), dict(right)
    r = left | right
    untouched = dict(left) == snap_l and dict(right) == snap_r
    return dict(r) == expected and untouched, '%s, operands untouched=%s' % (type(r).__name__, untouched)


def ior_vws():
    v = vws(a=1)
    orig = v
    v |= {'b': 2, 'a': 3}
    return v is orig and dict(v) == {'a': 3, 'b': 2}, '%s, same object=%s' % (type(v).__name__, v is orig)


def ior_dict():
    d = {'a': 1}
    d |= vws(b=2)
    return d == {'a': 1, 'b': 2} and type(d) is dict, type(d).__name__


def combine(a, b, expected, hash_behaviour='replace', **kw):
    def fn():
        with mock.patch('ansible.constants.DEFAULT_HASH_BEHAVIOUR', hash_behaviour):
            r = combine_vars(a(), b(), **kw)
        return dict(r) == expected, type(r).__name__
    return fn


def combine_raises(a, b):
    def fn():
        with mock.patch('ansible.constants.DEFAULT_HASH_BEHAVIOUR', 'replace'):
            return raises(AnsibleError, lambda: combine_vars(a(), b()))
    return fn


def debug_noise():
    big = {'k%d' % i: i for i in range(50)}
    with mock.patch.object(Display(), 'debug') as dbg:
        {'a': 1} | vws(**big)
        vws(**big) | {'a': 1}
    # informational: prefer 0, flags implementations that go through __getitem__
    return True, '%d display.debug calls for 2 unions over 50 vars' % dbg.call_count


def sources_kept():
    r = vws(a=1, c='x') | {'b': 2}
    if not isinstance(r, VarsWithSources):
        return True, 'result is %s (no sources to keep)' % type(r).__name__
    return r.get_source('a') == 'src_a', 'sources=%r' % (r.sources,)


# operator semantics
check('dict | VWS merges, right wins', lambda: union_case({'a': 1, 'c': 'l'}, vws(b=2, c='r'), {'a': 1, 'b': 2, 'c': 'r'}))
check('VWS | dict merges, right wins', lambda: union_case(vws(a=1, c='l'), {'b': 2, 'c': 'r'}, {'a': 1, 'b': 2, 'c': 'r'}))
check('VWS | VWS merges, right wins', lambda: union_case(vws(a=1, c='l'), vws(b=2, c='r'), {'a': 1, 'b': 2, 'c': 'r'}))
check('defaultdict | VWS', lambda: union_case(collections.defaultdict(list, a=1), vws(b=2), {'a': 1, 'b': 2}))
check('OrderedDict | VWS', lambda: union_case(collections.OrderedDict(a=1), vws(b=2), {'a': 1, 'b': 2}))
check('VWS |= dict is in place, returns self', ior_vws)
check('dict |= VWS stays a dict', ior_dict)
check('VWS | list -> TypeError', lambda: raises(TypeError, lambda: vws(a=1) | [('b', 2)]))
check('list | VWS -> TypeError', lambda: raises(TypeError, lambda: [('b', 2)] | vws(a=1)))
check('VWS | int -> TypeError', lambda: raises(TypeError, lambda: vws(a=1) | 1))
check('str | VWS -> TypeError', lambda: raises(TypeError, lambda: 'x' | vws(a=1)))
check('VWS | dict keeps left sources (if VWS)', sources_kept)

# combine_vars
check('combine_vars(dict, VWS) replace', combine(lambda: {'a': 1, 'c': 'a'}, lambda: vws(b=2, c='b'), {'a': 1, 'b': 2, 'c': 'b'}))
check('combine_vars(VWS, dict) replace', combine(lambda: vws(a=1, c='a'), lambda: {'b': 2, 'c': 'b'}, {'a': 1, 'b': 2, 'c': 'b'}))
check('combine_vars(VWS, VWS) replace', combine(lambda: vws(a=1), lambda: vws(b=2), {'a': 1, 'b': 2}))
check('combine_vars(list, VWS) -> AnsibleError', combine_raises(lambda: [1], lambda: vws(a=1)))
check('combine_vars(VWS, list) -> AnsibleError', combine_raises(lambda: vws(a=1), lambda: [1]))
check('combine_vars(dict, VWS) merge', combine(lambda: {'a': {'x': 1}}, lambda: vws(a={'y': 2}, b=2), {'a': {'x': 1, 'y': 2}, 'b': 2}, 'merge'))
check('combine_vars(merge=True) under replace', combine(lambda: {'a': {'x': 1}}, lambda: vws(a={'y': 2}), {'a': {'x': 1, 'y': 2}}, merge=True))

# informational
check('debug noise (info)', debug_noise)

print('RESULT: %d failure(s)%s' % (len(failures), (': ' + ', '.join(failures)) if failures else ''))
sys.exit(1 if failures else 0)

